update pages set contenu = '{"sections":[{"type":"heros","h1":"Bureau d''études mécanique : un plan qui tient au montage","mecanisme":"Nos ingénieurs conçoivent aux côtés de techniciens qui réparent des machines toute l''année. Cadrage, CAO, calculs, dossier de fabrication, puis montage et mise en service par les mêmes équipes.","cta":"Faire chiffrer mon étude","telephone":"04 78 33 72 05","phraseDelai":", du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 pour les urgences en cours de réalisation"},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, ingénieurs et projeteurs compris."},{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers."},{"valeur":"10","libelle":"hubs de techniciens, Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon, Nantes."}]},{"type":"probleme","punchline":"Un plan dessiné loin de l''atelier finit toujours par se payer au montage.","puces":[{"accroche":"Les idées restent des croquis.","texte":"Un équipement à faire évoluer, un poste à sécuriser, une ligne à modifier : le sujet attend son tour depuis des mois."},{"accroche":"Les devis fournisseurs sont incomparables.","texte":"Sans cahier des charges écrit, trois offres décrivent trois projets différents."},{"accroche":"Les modifications partent sans calcul.","texte":"Et la conformité de l''équipement modifié devient votre problème."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Assistance à maîtrise d''ouvrage","texte":"définition du besoin, étude de faisabilité, rédaction du cahier des charges, analyse comparée des offres"},"benefice":"Vos consultations se jouent sur des bases identiques. Le cahier des charges vous protège, y compris si vous confiez la suite à un autre"},{"prestation":{"accroche":"Conception et modélisation CAO","texte":"avant-projet, conception détaillée, choix des matériaux, des composants et des assemblages"},"benefice":"L''accessibilité des organes et l''entretien futur sont pensés dès le dessin, pas découverts à la première intervention"},{"prestation":{"accroche":"Calculs et simulation","texte":"résistance des matériaux, structure, thermique, sollicitations dynamiques, analyse vibratoire des machines tournantes"},"benefice":"Les problèmes se voient sur le calcul, pas sur le prototype. Une reprise en série coûte bien plus cher"},{"prestation":{"accroche":"Dossier de fabrication","texte":"plans d''ensemble et de détail, nomenclatures, spécifications, notices"},"benefice":"Vous consultez les ateliers de votre choix. Nous ne vendons ni machine ni composant, aucune marge cachée sur les pièces"},{"prestation":{"accroche":"Suivi de réalisation et réception des pièces","texte":"chez les ateliers retenus"},"benefice":"Les écarts se traitent avant le montage, pas pendant"},{"prestation":{"accroche":"Montage et mise en service","texte":"par nos propres équipes techniques"},"benefice":"Le même groupe porte le projet du plan à la machine qui tourne. Plus de renvoi de responsabilité entre celui qui conçoit, celui qui fabrique et celui qui pose"}]},{"type":"deroule","etapes":[{"titre":"Votre appel ou votre formulaire.","texte":"Un ingénieur vous rappelle dans l''heure pour comprendre le besoin, pas pour remplir une fiche."},{"titre":"Cadrage et faisabilité.","texte":"Usage, contraintes d''exploitation, environnement, budget, jalons. Sortie : un cahier des charges écrit."},{"titre":"Conception et modélisation.","texte":"L''avant-projet compare plusieurs solutions, la conception détaillée modélise l''équipement en CAO."},{"titre":"Calculs et simulation.","texte":"Dimensionnement vérifié, notes de calcul documentées. Prototypage ciblé quand un point sensible le justifie."},{"titre":"Dossier de fabrication.","texte":"Plans, nomenclatures, spécifications, notices. De quoi consulter et comparer."},{"titre":"Réalisation et réception.","texte":"Suivi de production chez les ateliers, réception des pièces avant montage."},{"titre":"Montage et mise en service.","texte":"Intégration dans votre ligne par nos équipes techniques, jusqu''à la production stabilisée."}]},{"type":"garanties","puces":[{"accroche":"Un rappel dans l''heure","texte":"du lundi au vendredi, 8h00 à 18h30, au 04 78 33 72 05, et une astreinte 24/24 et 7/7 pendant les phases de réalisation."},{"accroche":"Un chef de projet identifié","texte":", votre contact unique du cadrage à la réception, qui mobilise les compétences au fil du projet sans vous renvoyer d''un service à l''autre."},{"accroche":"Des compétences évaluées","texte":"comme nos techniciens, les membres de l''équipe d''études passent une évaluation technique et comportementale à l''entrée. Seuls 10 % des candidats sont retenus."},{"accroche":"Des interventions encadrées sur votre site","texte":"démarche MASE pour la sécurité des interventions, évaluation EcoVadis pour la performance RSE. Les attestations sont transmises avec chaque plan de prévention."}]},{"type":"cta","question":"Besoin de savoir ce que coûterait votre étude avant d''aller plus loin ?","bouton":"Faire chiffrer mon étude","href":"/contact/","rappel":"04 78 33 72 05, rappel dans l''heure"},{"type":"preuves","preuves":[{"titre":"[Étude de cas ORTHUS x ECOCEM : nouveau site](/preuves/orthus-ecocem/) · Pilotage complet de la construction d''un site industriel de recherche et développement près de Paris, coordination multi-métiers et jalons tenus."},{"titre":"[Étude de cas JOINT LYONNAIS : défaillances machines](/preuves/joint-lyonnais/) · Lyon, depuis février 2024. Diagnostic technique puis plusieurs solutions chiffrées, arbitrées par le client selon son budget."},{"titre":"[Étude de cas EATON : mise en production](/preuves/eaton-mise-en-production/) · Janvier 2023. Six techniciens multidisciplinaires pour l''installation et la mise en production d''un parc machines neuf."},{"titre":"[Étude de cas ORTHUS x WASHTEC : installation de stations](/preuves/orthus-washtec/) · Montage des portiques de lavage selon les standards du constructeur, réception, levage et raccordements, partout en France."}]},{"type":"objections","questions":[{"question":"Combien coûte une étude ?","reponse":"Chaque mission est chiffrée sur devis, sur la base d''un périmètre écrit. Pas d''heures de dessin vendues au kilomètre. Un petit projet bien cadré reste un petit budget."},{"question":"Pouvez-vous reprendre une étude commencée ailleurs ?","reponse":"Oui. Nous repartons de vos fichiers et de vos documents, nous vérifions les hypothèses de dimensionnement, et nous chiffrons la suite. Vos plans restent vos plans."},{"question":"Travaillez-vous avec notre logiciel de CAO interne ?","reponse":"Oui. Nous utilisons les standards du marché, Solid Edge, CATIA, Ansys, AutoCAD, et nous livrons des formats exploitables par vos équipes sous SolidWorks, Inventor ou Creo, avec vos règles de codification."},{"question":"Qui conçoit réellement mon projet ?","reponse":"Des ingénieurs et projeteurs salariés, évalués en entretien technique et comportemental : 10 % des candidats retenus, expérience de l''industrie exigée. Nos études ne sortent pas de bureaux où l''on n''a jamais serré un boulon."},{"question":"Pouvez-vous rédiger seulement le cahier des charges ?","reponse":"Oui, c''est une mission à part entière : définition du besoin, rédaction, consultation des fournisseurs, analyse des offres. Vous restez libre de confier la suite à qui vous voulez, y compris à un concurrent."},{"question":"Vos intervenants peuvent-ils travailler en sécurité sur notre site ?","reponse":"Oui. Le montage et la mise en service passent par un plan de prévention établi avec vos équipes. Nous y joignons les attestations de notre démarche MASE et de notre évaluation EcoVadis. Vous savez qui entre chez vous."},{"question":"Intervenez-vous partout en France ?","reponse":"Oui. Quatre agences, Lyon (siège, à Limonest et Écully), Montréal, Dubaï et Madrid, et dix hubs de techniciens à Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon et Nantes. Ailleurs, nos équipes se déplacent : le montage et la mise en service se font sur votre site, où qu''il soit. Nous accompagnons aussi hors de France les clients qui y exploitent des sites."}]},{"type":"ctaFinal","question":"Besoin d''un ingénieur qui comprenne votre projet dès le premier appel ?","bouton":"Faire chiffrer mon étude","href":"/contact/","rappel":"04 78 33 72 05"}]}'::jsonb where path = '/offres/bureau-etudes/';
